package com.example.Backend.Entity;

import jakarta.persistence.*;
import lombok.*;

import java.time.LocalDateTime;
import java.util.List;

@Entity
@Table(name = "test_results", indexes = {
    @Index(name = "idx_test_results_session", columnList = "session_id", unique = true),
    @Index(name = "idx_test_results_completed_at", columnList = "completed_at")
})
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
public class TestResult {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** UUID generated by frontend — used to prevent duplicate submissions */
    @Column(name = "session_id", nullable = false, unique = true, length = 64)
    private String sessionId;

    @Column(nullable = false)
    private String testName;

    @Column(nullable = false)
    private LocalDateTime completedAt;

    /** Total elapsed seconds for the entire session */
    @Column(nullable = false)
    private Integer overallTimeSecs;

    @Column(nullable = false)
    private Integer totalScore;

    @Column(nullable = false)
    private Integer totalMaxMarks;

    @Column(nullable = false)
    private Integer totalCorrect;

    @Column(nullable = false)
    private Integer totalWrong;

    @Column(nullable = false)
    private Integer totalAttempted;

    @Column(nullable = false)
    private Double accuracyPercent;

    @OneToMany(mappedBy = "testResult", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    private List<SubjectResult> subjectResults;
}
